<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/app/music-library-preparation.php';
function mp_ok(bool $ok,string $label):void{if(!$ok)throw new RuntimeException($label);echo "PASS music preparation: $label\n";}
function mp_no(callable $fn,string $label):void{try{$fn();}catch(Throwable){mp_ok(true,$label);return;}throw new RuntimeException($label);}
function mp_tag(string $id,string $text):string{$v="\x03".$text;return $id.pack('N',strlen($v))."\0\0".$v;}
$dir=sys_get_temp_dir().'/rr-preparation-'.bin2hex(random_bytes(5));mkdir($dir,0700);$dir=realpath($dir);$root=$dir.'/media/music';$user=['role'=>'producer','id'=>'synthetic'];
$tags=mp_tag('TIT2','Testlåt').mp_tag('TPE1','Testartist').mp_tag('TALB','Testalbum').mp_tag('TCON','Pop').mp_tag('TYER','2020');$size=strlen($tags);$bytes="ID3\x03\0\0".pack('C4',($size>>21)&127,($size>>14)&127,($size>>7)&127,$size&127).$tags.str_repeat(hex2bin('fffb9000').str_repeat("\0",413),100);
$tmp=$dir.'/fixture.mp3';file_put_contents($tmp,$bytes);$file=['name'=>'random-prefix.mp3','tmp_name'=>$tmp,'size'=>strlen($bytes),'error'=>0];
try{$r=music_library_upload($file,$user,'c','c',$root,static fn($p)=>is_file($p),static fn($a,$b)=>copy($a,$b));$t=$r['track'];$id=$t['id'];$sha=$t['sha256'];$before=file_get_contents($root.'/library.json');
 mp_no(fn()=>music_library_prepare($id,$sha,0,['role'=>'observer'],'c','c',$root),'observer denied');mp_no(fn()=>music_library_prepare($id,$sha,0,$user,'bad','c',$root),'CSRF denied');mp_no(fn()=>music_library_prepare($id,str_repeat('a',64),0,$user,'c','c',$root),'wrong source denied');mp_no(fn()=>music_library_prepare($id,$sha,1,$user,'c','c',$root),'stale revision denied');mp_ok(file_get_contents($root.'/library.json')===$before,'denials write nothing');
 $prepared=music_library_prepare($id,$sha,0,$user,'c','c',$root);$m=music_library_metadata($prepared);mp_ok($m['fields']['artist']==='Testartist'&&$m['fields']['title']==='Testlåt'&&$m['fields']['album']==='Testalbum','actual ID3 fields read');mp_ok($m['durationSeconds']>2&&$m['durationSeconds']<3,'duration measured from frames');mp_ok($m['source']==='file'&&$m['sourceSha256']===$sha&&$prepared['revision']===1,'source identity and revision recorded');mp_ok(hash_file('sha256',$root.'/originals/'.$id.'.mp3')===$sha,'original untouched');
 $h=music_library_verified_handle($prepared,$root);mp_ok(stream_get_contents($h)===$bytes,'verified handle returns original bytes');fclose($h);$after=file_get_contents($root.'/library.json');mp_no(fn()=>music_library_prepare($id,$sha,0,$user,'c','c',$root),'old revision cannot overwrite analysis');mp_ok(file_get_contents($root.'/library.json')===$after,'stale analysis preserves metadata');
 mp_ok(music_library_metadata(array_replace($prepared,['sha256'=>str_repeat('b',64)]))===null,'changed source invalidates displayed metadata');
 file_put_contents($root.'/originals/'.$id.'.mp3',str_repeat('x',strlen($bytes)));mp_no(fn()=>music_library_prepare($id,$sha,1,$user,'c','c',$root),'same-size original tamper denied');mp_no(fn()=>music_library_verified_handle($prepared,$root),'tampered audio cannot stream');mp_ok(file_get_contents($root.'/library.json')===$after,'tamper does not overwrite previous metadata');
}finally{foreach(new RecursiveIteratorIterator(new RecursiveDirectoryIterator($dir,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::CHILD_FIRST)as$f)$f->isDir()?rmdir($f->getPathname()):unlink($f->getPathname());rmdir($dir);}
